/**
 * ui-tooltip — root compound element (Zag tooltip behind the facade).
 *   <ui-tooltip open.two-way="isOpen" open-change.trigger="...">
 */
import { customElement, bindable, BindingMode, INode, resolve } from 'aurelia'
import {
  createTooltipBehavior,
  createControlledSync,
  createContext,
  createId,
  type ControlledSync,
  type TooltipApi,
  type BehaviorSource,
} from '@shadcn-aurelia/primitives'

export const tooltipContext = createContext<UiTooltip>()

@customElement({ name: 'ui-tooltip', template: '<au-slot></au-slot>' })
export class UiTooltip implements BehaviorSource<TooltipApi> {
  @bindable({ mode: BindingMode.twoWay }) open = false

  private readonly host: HTMLElement = resolve(INode) as HTMLElement
  private readonly behavior = createTooltipBehavior()
  private sync: ControlledSync<boolean> | null = null

  get api(): TooltipApi | null {
    return this.behavior.api
  }

  subscribe(listener: () => void): () => void {
    return this.behavior.subscribe(listener)
  }

  binding(): void {
    tooltipContext.set(this.host, this)
    this.sync = createControlledSync<boolean>({
      host: this.host,
      eventName: 'open-change',
      setMachineValue: (v) => this.behavior.api?.setOpen(v),
      setBindable: (v) => (this.open = v),
    })
    this.behavior.init({
      id: createId('tooltip'),
      defaultOpen: this.open,
      onOpenChange: (d: { open: boolean }) => this.sync?.fromMachine(d.open),
    })
  }

  attached(): void {
    this.behavior.start()
  }

  openChanged(v: boolean): void {
    this.sync?.fromBindable(v)
  }

  detaching(): void {
    this.behavior.stop()
    tooltipContext.delete(this.host)
  }
}

/**
 * ui-tooltip-trigger — applies Zag trigger props to the host so the slotted
 * interactive child (button, link) activates the tooltip via bubbling events.
 */
import { customElement, INode, resolve } from 'aurelia'
import { bindPart } from '@shadcn-aurelia/primitives'
import { tooltipContext } from './tooltip'

@customElement({ name: 'ui-tooltip-trigger', template: '<au-slot></au-slot>' })
export class UiTooltipTrigger {
  private readonly host: HTMLElement = resolve(INode) as HTMLElement
  private dispose: (() => void) | null = null

  attached(): void {
    const tooltip = tooltipContext.get(this.host)
    if (!tooltip) {
      console.warn('[ui-tooltip-trigger] No parent <ui-tooltip> found in DOM')
      return
    }
    this.dispose = bindPart(tooltip, this.host, (api) => api.getTriggerProps())
  }

  detaching(): void {
    this.dispose?.()
    this.dispose = null
  }
}

/**
 * ui-tooltip-content — overlay panel, portaled to <body>; positioner receives
 * Zag's floating-ui styles, content gets role/data-state plus shadcn classes.
 */
import { customElement, INode, resolve } from 'aurelia'
import { bindPart } from '@shadcn-aurelia/primitives'
import { cn } from '@/registry/default/lib/cn'
import { tooltipContext } from './tooltip'

const CONTENT_TEMPLATE = `
<div ref="positionerEl" data-slot="tooltip-positioner">
  <div ref="contentEl" data-slot="tooltip-content" class.bind="classes">
    <au-slot></au-slot>
  </div>
</div>
`

@customElement({ name: 'ui-tooltip-content', template: CONTENT_TEMPLATE })
export class UiTooltipContent {
  positionerEl!: HTMLDivElement
  contentEl!: HTMLDivElement

  private readonly host: HTMLElement = resolve(INode) as HTMLElement
  private disposers: Array<() => void> = []
  private authorClasses = ''

  bound(): void {
    this.authorClasses = this.host.getAttribute('class') ?? ''
  }

  get classes(): string {
    return cn(
      'z-50 w-fit rounded-md bg-primary px-3 py-1.5 text-xs text-balance text-primary-foreground',
      this.authorClasses,
    )
  }

  attached(): void {
    // resolve context BEFORE the portal moves the element out of the tree
    const tooltip = tooltipContext.get(this.host)
    document.body.appendChild(this.host)
    if (!tooltip) {
      console.warn('[ui-tooltip-content] No parent <ui-tooltip> found in DOM')
      return
    }
    this.disposers = [
      bindPart(tooltip, this.positionerEl, (api) => api.getPositionerProps()),
      bindPart(tooltip, this.contentEl, (api) => api.getContentProps()),
    ]
  }

  detaching(): void {
    this.disposers.forEach((d) => d())
    this.disposers = []
  }
}
